{"content": """"
Tagging system for MemPalace - context and palace tagging
"""

import os
import re
from typing import List, Dict, Set

# Storage path - will be set by init_tagging
_STORAGE_PATH = None

# Context tag taxonomy - can be extended
CONTEXT_TAG_TAXONOMY = {
    'technical': ['code', 'programming', 'debugging', 'algorithm', 'database', 'api', 'framework', 'library'],
    'business': ['meeting', 'project', 'deadline', 'client', 'sales', 'marketing', 'finance', 'strategy'],
    'personal': ['health', 'exercise', 'food', 'travel', 'family', 'friends', 'hobby', 'learning'],
    'creative': ['writing', 'design', 'art', 'music', 'brainstorm', 'idea', 'concept'],
    'research': ['paper', 'study', 'experiment', 'data', 'analysis', 'hypothesis', 'literature'],
    'communication': ['email', 'message', 'call', 'presentation', 'discussion', 'feedback']
}

# Palace tag mapping - maps context tags to memory palaces
PALACE_TAG_MAPPING = {
    'technical': 'workshop',
    'business': 'office',
    'personal': 'home',
    'creative': 'studio',
    'research': 'library',
    'communication': 'hall'
}

def init_tagging(storage_path):
    """Initialize tagging system"""
    global _STORAGE_PATH
    _STORAGE_PATH = storage_path

def extract_context_tags(text: str) -> List[str]:
    """Extract context tags from text based on taxonomy"""
    if not text:
        return []

    text_lower = text.lower()
    tags = set()

    for category, keywords in CONTEXT_TAG_TAXONOMY.items():
        for keyword in keywords:
            # Use word boundaries to avoid partial matches
            if re.search(r'\b' + re.escape(keyword) + r'\b', text_lower):
                tags.add(category)
                break  # One match per category is enough

    return list(tags)

def extract_palace_tags(context_tags: List[str]) -> List[str]:
    """Derive palace tags from context tags"""
    palace_tags = set()
    for tag in context_tags:
        if tag in PALACE_TAG_MAPPING:
            palace_tags.add(PALACE_TAG_MAPPING[tag])

    # If no palace tags found, use a default
    if not palace_tags:
        palace_tags.add('atrium')  # Default palace

    return list(palace_tags)

def tag_event(event_data: dict) -> dict:
    """Add context and palace tags to event data"""
    # Extract text content for tagging
    text_content = ""
    if isinstance(event_data, dict):
        # Try common content fields
        for field in ['content', 'text', 'message', 'description', 'title']:
            if field in event_data and isinstance(event_data[field], str):
                text_content = event_data[field]
                break

    # If no text found, use string representation
    if not text_content:
        text_content = str(event_data)

    context_tags = extract_context_tags(text_content)
    palace_tags = extract_palace_tags(context_tags)

    # Add tags to event data
    tagged_data = event_data.copy() if isinstance(event_data, dict) else {'raw_data': event_data}
    tagged_data['context_tags'] = context_tags
    tagged_data['palace_tags'] = palace_tags

    return tagged_data", "path": "~/.hermes/mempalace/tag.py"}

{"content": """"
Reinforcement system for MemPalace - usage-based memory reinforcement
"""

import os
import json
from datetime import datetime, timezone

# Storage path - will be set by init_reinforcement
_STORAGE_PATH = None
_REINFORCEMENT_FILE = None

def init_reinforcement(storage_path):
    """Initialize reinforcement system"""
    global _STORAGE_PATH, _REINFORCEMENT_FILE
    _STORAGE_PATH = storage_path
    prefs_dir = os.path.join(_STORAGE_PATH, 'preferences')
    os.makedirs(prefs_dir, exist_ok=True)
    _REINFORCEMENT_FILE = os.path.join(prefs_dir, 'reinforcement.jsonl')

    # Ensure file exists
    if not os.path.exists(_REINFORCEMENT_FILE):
        with open(_REINFORCEMENT_FILE, 'w') as f:
            pass  # Create empty file

def reinforce_memory(memory_id, context=""):
    """Reinforce a memory by logging its successful use"""
    if not _STORAGE_PATH or not _REINFORCEMENT_FILE:
        raise RuntimeError("Reinforcement system not initialized. Call init_reinforcement first.")

    reinforcement_event = {
        'memory_id': memory_id,
        'timestamp': datetime.now(timezone.utc).isoformat(),
        'context': context
    }

    try:
        with open(_REINFORCEMENT_FILE, 'a') as f:
            f.write(json.dumps(reinforcement_event) + '\n')
    except Exception as e:
        print(f"Failed to write reinforcement event: {e}")

def get_reinforced_memories(limit=100):
    """Get memories sorted by reinforcement count"""
    if not _STORAGE_PATH or not _REINFORCEMENT_FILE:
        return []

    # Count reinforcements per memory ID
    reinforcement_counts = {}

    try:
        with open(_REINFORCEMENT_FILE, 'r') as f:
            for line in f:
                line = line.strip()
                if line:
                    try:
                        event = json.loads(line)
                        mem_id = event.get('memory_id')
                        if mem_id:
                            reinforcement_counts[mem_id] = reinforcement_counts.get(mem_id, 0) + 1
                    except json.JSONDecodeError:
                        continue
    except Exception as e:
        print(f"Error reading reinforcement file: {e}")
        return []

    # Sort by count (descending) and get top memories
    sorted_memories = sorted(reinforcement_counts.items(), key=lambda x: x[1], reverse=True)

    # Get the actual memory objects for top memories
    results = []
    from . import retrieve
    for mem_id, count in sorted_memories[:limit]:
        memory = retrieve.get_memory_by_id(mem_id)
        if memory:
            memory['reinforcement_count'] = count
            results.append(memory)

    return results

def get_reinforcement_count(memory_id):
    """Get reinforcement count for a specific memory"""
    if not _STORAGE_PATH or not _REINFORCEMENT_FILE:
        return 0

    count = 0
    try:
        with open(_REINFORCEMENT_FILE, 'r') as f:
            for line in f:
                line = line.strip()
                if line:
                    try:
                        event = json.loads(line)
                        if event.get('memory_id') == memory_id:
                            count += 1
                    except json.JSONDecodeError:
                        continue
    except Exception:
        pass

    return count", "path": "~/.hermes/mempalace/reinforce.py"}

{"content": """"
Pruning system for MemPalace - memory pruning with archiving
"""

import os
import json
import shutil
from datetime import datetime, timezone
from . import score, capture

# Storage path - will be set by init_pruning
_STORAGE_PATH = None

# Pruning thresholds
PRUNE_AGE_DAYS = 30  # Memories older than this are candidates for pruning
PRUNE_SCORE_THRESHOLD = 0.3  # Memories scoring below this are pruned
ARCHIVE_DIR = 'archive'

def init_pruning(storage_path):
    """Initialize pruning system"""
    global _STORAGE_PATH
    _STORAGE_PATH = storage_path

    # Ensure archive directory exists
    archive_path = os.path.join(_STORAGE_PATH, ARCHIVE_DIR)
    os.makedirs(archive_path, exist_ok=True)

def prune_memories(dry_run=False):
    """Prune low-value, old memories"""
    if not _STORAGE_PATH:
        raise RuntimeError("Pruning system not initialized. Call init_pruning first.")

    pruned_count = 0
    archived_count = 0

    # Prune raw memories
    pruned_raw, archived_raw = _prune_raw_memories(dry_run)
    pruned_count += pruned_raw
    archived_count += archived_raw

    # Note: We typically don't prune consolidated memories as they represent important knowledge
    # But we could add logic to prune very old consolidated memories if needed

    return {
        'pruned': pruned_count,
        'archived': archived_count,
        'dry_run': dry_run
    }

def _prune_raw_memories(dry_run=False):
    """Prune raw memory events"""
    pruned = 0
    archived = 0

    if not _STORAGE_PATH:
        return pruned, archived

    raw_dir = os.path.join(_STORAGE_PATH, 'raw')
    archive_dir = os.path.join(_STORAGE_PATH, ARCHIVE_DIR, 'raw')
    os.makedirs(archive_dir, exist_ok=True)

    # Calculate cutoff date
    cutoff_date = datetime.now(timezone.utc) - timedelta(days=PRUNE_AGE_DAYS)

    # Process each raw file
    if os.path.exists(raw_dir):
        for filename in os.listdir(raw_dir):
            if filename.endswith('.jsonl'):
                filepath = os.path.join(raw_dir, filename)
                archive_filepath = os.path.join(archive_dir, filename)

                # Read all events
                kept_lines = []
                pruned_lines = []

                try:
                    with open(filepath, 'r') as f:
                        for line_num, line in enumerate(f, 1):
                            line = line.strip()
                            if not line:
                                continue

                            try:
                                event = json.loads(line)
                                # Validate it's a dict
                                if not isinstance(event, dict):
                                    # Keep non-dict lines (they might be valid in some contexts)
                                    kept_lines.append(line)
                                    continue

                                # Check if event should be pruned
                                timestamp_str = event.get('timestamp', '')
                                should_prune = False

                                if timestamp_str:
                                    try:
                                        # Handle both timezone-aware and naive timestamps
                                        if timestamp_str.endswith('Z'):
                                            timestamp_str = timestamp_str[:-1] + '+00:00'
                                        timestamp = datetime.fromisoformat(timestamp_str)
                                        # Ensure timezone-aware (assume UTC if naive)
                                        if timestamp.tzinfo is None:
                                            timestamp = timestamp.replace(tzinfo=timezone.utc)
                                        else:
                                            timestamp = timestamp.astimezone(timezone.utc)

                                        # Check age
                                        if timestamp < cutoff_date:
                                            # Check score (need to score the event)
                                            event_score = score.score_event(event)
                                            if event_score < PRUNE_SCORE_THRESHOLD:
                                                should_prune = True
                                    except Exception as e:
                                        print(f"Error parsing timestamp in {filepath}:{line_num}: {e}")
                                        # On error, keep the memory (don't prune)

                                if should_prune:
                                    pruned_lines.append(line)
                                    pruned += 1
                                else:
                                    kept_lines.append(line)

                            except json.JSONDecodeError as e:
                                print(f"Invalid JSON in {filepath}:{line_num}: {e}")
                                # Keep invalid JSON lines (safer)
                                kept_lines.append(line)

                    # Write back kept lines or archive if dry_run=False
                    if dry_run:
                        # Just count what would be pruned
                        pass
                    else:
                        if pruned_lines > 0:
                            # Archive the pruned lines
                            if pruned_lines:
                                with open(archive_filepath, 'a') as f:
                                    for line in pruned_lines:
                                        f.write(line + '\n')

                                # Rewrite original file with kept lines
                                with open(filepath, 'w') as f:
                                    for line in kept_lines:
                                        f.write(line + '\n')

                                archived += len(pruned_lines)
                        # If no lines pruned, keep original file

                except Exception as e:
                    print(f"Error processing {filepath}: {e}")

    return pruned, archived

def get_pruning_stats():
    """Get statistics about pruning candidates"""
    if not _STORAGE_PATH:
        return {}

    stats = {
        'total_raw_memories': 0,
        'candidates_for_pruning': 0,
        'would_be_pruned': 0,
        'archive_size_mb': 0
    }

    raw_dir = os.path.join(_STORAGE_PATH, 'raw')
    archive_dir = os.path.join(_STORAGE_PATH, ARCHIVE_DIR, 'raw')

    # Count raw memories
    if os.path.exists(raw_dir):
        for filename in os.listdir(raw_dir):
            if filename.endswith('.jsonl'):
                filepath = os.path.join(raw_dir, filename)
                try:
                    with open(filepath, 'r') as f:
                        for line in f:
                            line = line.strip()
                            if line:
                                try:
                                    event = json.loads(line)
                                    if isinstance(event, dict):
                                        stats['total_raw_memories'] += 1
                                except json.JSONDecodeError:
                                    pass
                except Exception:
                    pass

    # Count archive size
    if os.path.exists(archive_dir):
        total_size = 0
        for filename in os.listdir(archive_dir):
            filepath = os.path.join(archive_dir, filename)
            if os.path.isfile(filepath):
                total_size += os.path.getsize(filepath)
        stats['archive_size_mb'] = round(total_size / (1024 * 1024), 2)

    return stats

# Import timedelta at the top level to avoid issues
